51	static void fb_fill(int x, int y, int w, int h, uint16_t c)
52	{
53	  volatile uint16_t *fb = (volatile uint16_t *)0xc0000000;
54	  int yy, xx;
55	
56	  if (x < 0) { w += x; x = 0; }
57	  if (y < 0) { h += y; y = 0; }
58	  if (x + w > LCD_W) { w = LCD_W - x; }
59	  if (y + h > LCD_H) { h = LCD_H - y; }
60	  if (w <= 0 || h <= 0) { return; }
61	
62	  for (yy = 0; yy < h; yy++)
63	    {
64	      uint16_t *row = (uint16_t *)fb + (y + yy) * LCD_W + x;
65	      for (xx = 0; xx < w; xx++) { row[xx] = c; }
66	    }
67	}
68	
69	static void fb_px(int x, int y, uint16_t c)
70	{
71	  if (x >= 0 && x < LCD_W && y >= 0 && y < LCD_H)
72	    {
73	      ((volatile uint16_t *)0xc0000000)[y * LCD_W + x] = c;
74	    }
75	}
