80	
81	static void draw_gray4(int x, int y, int w, int h, const uint8_t *bits,
82	                       int scale)
83	{
84	  volatile uint16_t *fb = (volatile uint16_t *)0xc0000000;
85	  int yy, xx, dy, dx;
86	
87	  for (yy = 0; yy < h; yy++)
88	    {
89	      for (xx = 0; xx < w; xx++)
90	        {
91	          int b = bits[yy * (w / 2) + (xx >> 1)];
92	          int v = (xx & 1) ? (b & 0x0f) : (b >> 4);
93	
94	          if (v == 0) { continue; }
95	
96	          for (dy = 0; dy < scale; dy++)
97	            {
98	              int sy = y + yy * scale + dy;
99	              if (sy < 0 || sy >= LCD_H) { continue; }
100	              for (dx = 0; dx < scale; dx++)
101	                {
102	                  int sx = x + xx * scale + dx;
103	                  if (sx < 0 || sx >= LCD_W) { continue; }
104	                  {
105	                    /* v41: linear blackness -> RGB565.  v=15 (pure black
106	                     * glyph pixel) now maps to 0x0000.
107	                     */
108	                    int br = 15 - v;              /* 0..15 brightness */
109	                    int r5 = (br * 31 + 7) / 15;  /* 0..31 */
110	                    int g6 = (br * 63 + 7) / 15;  /* 0..63 */
111	                    int b5 = (br * 31 + 7) / 15;  /* 0..31 */
112	                    fb[sy * LCD_W + sx] = (uint16_t)((r5 << 11) |
113	                                                     (g6 << 5) | b5);
114	                  }
115	                }
116	            }
117	        }
118	    }
119	}
