207	static void draw_line(int x0, int y0, int x1, int y1, int w, uint16_t c)
208	{
209	  int dx = abs(x1 - x0);
210	  int dy = -abs(y1 - y0);
211	  int sx = x0 < x1 ? 1 : -1;
212	  int sy = y0 < y1 ? 1 : -1;
213	  int err = dx + dy;
214	
215	  for (;;)
216	    {
217	      draw_circle(x0, y0, w / 2, c);
218	      if (x0 == x1 && y0 == y1) { break; }
219	      {
220	        int e2 = 2 * err;
221	        if (e2 >= dy) { err += dy; x0 += sx; }
222	        if (e2 <= dx) { err += dx; y0 += sy; }
223	      }
