369	 */
370	#define NCR_JUMP 260
371	
372	static void ncr_add(int x, int y)
373	{
374	  if (g_ncr_n > 0)
375	    {
376	      int dx = x - g_ncr_x[g_ncr_n - 1];
377	      int dy = y - g_ncr_y[g_ncr_n - 1];
378	
379	      if (dx * dx + dy * dy > NCR_JUMP * NCR_JUMP)
380	        {
381	          return;   /* carry-jump / glitch sample */
382	        }
383	    }
384	
385	  if (g_ncr_n < NCR_MAX_PTS)
386	    {
387	      g_ncr_x[g_ncr_n] = x;
388	      g_ncr_y[g_ncr_n] = y;
389	      g_ncr_n++;
390	    }
391	}
392	
393	static void ncr_rasterize(uint8_t grid[NCR_N][NCR_N])
394	{
395	  int minx, miny, maxx, maxy, i;
396	  int w, h, gw, gh, ox, oy;
397	  float s;
398	  uint8_t tmp[NCR_N][NCR_N];
399	
400	  minx = maxx = g_ncr_x[0];
401	  miny = maxy = g_ncr_y[0];
402	
403	  for (i = 1; i < g_ncr_n; i++)
404	    {
405	      if (g_ncr_x[i] < minx) { minx = g_ncr_x[i]; }
406	      if (g_ncr_x[i] > maxx) { maxx = g_ncr_x[i]; }
407	      if (g_ncr_y[i] < miny) { miny = g_ncr_y[i]; }
408	      if (g_ncr_y[i] > maxy) { maxy = g_ncr_y[i]; }
409	    }
410	
411	  w = maxx - minx + 1;
412	  h = maxy - miny + 1;
413	  if (w < 1) { w = 1; }
414	  if (h < 1) { h = 1; }
415	
416	  s = (float)(NCR_N - 2) / (w > h ? w : h);
417	  gw = (int)(w * s);
418	  gh = (int)(h * s);
419	  if (gw < 1) { gw = 1; }
420	  if (gh < 1) { gh = 1; }
421	  ox = (NCR_N - gw) / 2;
422	  oy = (NCR_N - gh) / 2;
423	
424	  memset(grid, 0, NCR_N * NCR_N);
425	
426	  for (i = 0; i < g_ncr_n; i++)
427	    {
428	      int gx = ox + (int)((g_ncr_x[i] - minx) * s);
429	      int gy = oy + (int)((g_ncr_y[i] - miny) * s);
430	
431	      if (gx >= 0 && gx < NCR_N && gy >= 0 && gy < NCR_N)
432	        {
433	          grid[gy][gx] = 1;
434	        }
435	    }
436	
437	  /* dilate once (8-neighbour) so thin strokes thicken up */
438	  memcpy(tmp, grid, sizeof(tmp));
439	  for (i = 0; i < NCR_N * NCR_N; i++)
440	    {
441	      int gx = i % NCR_N;
442	      int gy = i / NCR_N;
443	      int dx, dy;
444	
445	      if (!tmp[gy][gx]) { continue; }
446	
447	      for (dy = -1; dy <= 1; dy++)
448	        {
449	          for (dx = -1; dx <= 1; dx++)
450	            {
451	              int nx = gx + dx;
452	              int ny = gy + dy;
453	
454	              if (nx >= 0 && nx < NCR_N && ny >= 0 && ny < NCR_N)
455	                {
456	                  grid[ny][nx] = 1;
457	                }
458	            }
459	        }
460	    }
461	}
462	
463	static int ncr_match(const uint8_t grid[NCR_N][NCR_N], int tmpl)
464	{
465	  int best = 0;
466	  int dx, dy;
467	
468	  /* tolerate +/-1 cell misalignment: the stroke may sit slightly off
469	   * centre in the 16x16 box (e.g. a '1' drawn at the box edge) */
470	  for (dy = -1; dy <= 1; dy++)
471	    {
472	      for (dx = -1; dx <= 1; dx++)
473	        {
474	          int hit = 0, tot = 0, thit = 0, ttot = 0;
475	          int x, y;
476	
477	          for (y = 0; y < NCR_N; y++)
478	            {
479	              for (x = 0; x < NCR_N; x++)
480	                {
481	                  int gx = x - dx;
482	                  int gy = y - dy;
483	                  int g = (gx >= 0 && gx < NCR_N && gy >= 0 && gy < NCR_N) ?
484	                          grid[gy][gx] : 0;
485	                  int bit = (ncr_tmpl[tmpl][y * 2 + (x >> 3)] >>
486	                             (7 - (x & 7))) & 1;
487	
488	                  if (g)
489	                    {
490	                      tot++;
491	                      if (bit) { hit++; }
492	                    }
493	
494	                  if (bit)
495	                    {
496	                      ttot++;
497	                      if (g) { thit++; }
498	                    }
499	                }
500	            }
501	
502	          if (tot > 0 && ttot > 0)
503	            {
504	              /* average of both coverage directions (F1-like) */
505	              int sc = (hit * 1000 / tot + thit * 1000 / ttot) / 2;
506	
507	              if (sc > best) { best = sc; }
508	            }
509	        }
510	    }
511	
512	  return best;
513	}
514	
515	static int ncr_recognize(void)
516	{
517	  uint8_t grid[NCR_N][NCR_N];
518	  int best = -1, bestsc = 0;
519	  int t;
520	
521	  if (g_ncr_n < 8)
522	    {
523	      return -1;
524	    }
525	
526	  ncr_rasterize(grid);
527	
528	  for (t = 0; t < 10; t++)
529	    {
530	      int sc = ncr_match(grid, t);
531	
532	      if (sc > bestsc)
533	        {
534	          bestsc = sc;
535	          best = t;
536	        }
537	    }
538	
539	  return (bestsc >= 250) ? best : -1;
540	}
