679	/* ------------------------------------------------------------------ */
680	/* ADC + DAC + FFT spectrum analyser (v55)                             */
681	/* ------------------------------------------------------------------ */
682	/* Register-only access (no kernel driver change), same style as the
683	 * TLI/GT911 bring-up:
684	 *   ADC0  = 0x40012400, 14-bit, CH18 = PA4 (external signal input)
685	 *   RCU   = 0x58024400  APB2EN +0x44 bit8=ADC0,
686	 *                        AHB4EN +0x3C bit0=GPIOA (already on)
687	 *   GPIOA = 0x58020000  PA4 analog: CTL bits[9:8]=11, PUD bits[9:8]=00
688	 */
689	#define VREG(a)     (*(volatile uint32_t *)(a))
690	#define ADC0_BASE   0x40012400UL
691	#define RCU_BASE    0x58024400UL
692	#define GPIOA_BASE  0x58020000UL
693	
694	#define ADC_STAT    VREG(ADC0_BASE + 0x00)
695	#define ADC_CTL0    VREG(ADC0_BASE + 0x04)
696	#define ADC_CTL1    VREG(ADC0_BASE + 0x08)
697	#define ADC_RSQ0    VREG(ADC0_BASE + 0x24)
698	#define ADC_RSQ8    VREG(ADC0_BASE + 0x44)
699	#define ADC_RDATA   VREG(ADC0_BASE + 0x64)
700	#define ADC_SYNCCTL VREG(ADC0_BASE + 0x304)
701	#define RCU_APB2EN  VREG(RCU_BASE + 0x44)
702	#define GPIOA_CTL   VREG(GPIOA_BASE + 0x00)
703	#define GPIOA_PUD   VREG(GPIOA_BASE + 0x0C)
704	
705	#define FFT_N   256
706	#define SP_X    30
707	#define SP_Y    95
708	#define SP_W    360
709	#define SP_H    320
710	#define FF_X    410
711	#define FF_Y    95
712	#define FF_W    360
713	#define FF_H    320
714	
715	static float g_re[FFT_N];
716	static float g_im[FFT_N];
717	static int   g_spec_inited = 0;
718	static int   g_adc_min = 0;
719	static int   g_adc_max = 0;
720	static int   g_adc_avg = 0;
721	static int   g_adc_err = 0;
722	
723	
724	/* RCU APB2 reset control: +0x24, ADC0RST = bit8 (example18 adc_deinit) */
725	#define RCU_APB2RST  VREG(RCU_BASE + 0x24)
726	#define RCU_APB4EN   VREG(RCU_BASE + 0x4C)
727	#define VREF_CS_REG  VREG(0x58003800)
728	
729	/* enable internal voltage reference: VREFP = 2.5V for ADC */
730	static void vref_enable(void)
731	{
732	  RCU_APB4EN |= (1u << 2);                 /* VREF clock on (APB4EN bit2) */
733	  VREF_CS_REG = (VREF_CS_REG & ~(0x3u << 4)) | (0u << 4); /* VREFS = 2.5V */
734	  VREF_CS_REG &= ~(1u << 1);               /* HIPM = 0 (drive VREFP pin) */
735	  VREF_CS_REG |= (1u << 0);                /* VREFEN = 1 */
736	  { int w = 0; while (!(VREF_CS_REG & (1u << 3)) && (++w < 100000)) ; }
737	}
738	
739	static void adc0_init(void)
740	{
741	  vref_enable();
742	  RCU_APB2EN |= (1u << 8);                 /* ADC0 clock on */
743	  RCU_APB2RST |= (1u << 8);                /* adc_deinit: reset ADC0 */
744	  RCU_APB2RST &= ~(1u << 8);
745	
746	  GPIOA_CTL = (GPIOA_CTL & ~(3u << 8)) | (3u << 8);  /* PA4 analog */
747	  GPIOA_PUD &= ~(3u << 8);
748	
749	  ADC_CTL1 &= ~(1u << 0);                  /* ADC off during config */
750	  ADC_SYNCCTL = (ADC_SYNCCTL & ~((0xFu << 16) | (0xFu << 20))) | 0x000C0000u;
751	  ADC_SYNCCTL &= ~(0xFu << 0);             /* sync mode: independent (=0) */
752	  ADC_CTL0 &= ~(0x3u << 24);               /* 14-bit resolution */
753	  ADC_CTL0 &= ~(1u << 8);                  /* scan mode off */
754	  ADC_CTL1 &= ~(1u << 1);                  /* continuous mode off */
755	  ADC_CTL1 &= ~(1u << 11);                 /* right aligned */
756	  ADC_CTL1 &= ~(0x3u << 28);               /* ext trigger disable (ETMRC=0) */
757	  ADC_RSQ0 &= ~(0xFu << 20);               /* 1 conversion in sequence */
758	  ADC_RSQ8 = ((807u & 0x3FFu) << 5) | 0x12u;  /* rank0 = CH18, 807-clk */
759	
760	  ADC_CTL1 |= (1u << 0);                   /* ADC on */
761	  usleep(10000);                           /* wait ADC stable, then calibrate */
762	  ADC_CTL1 |= (1u << 27);                  /* calibration mode OFFSET (lib) */
763	  ADC_CTL1 &= ~(0x7u << 4);                /* calibration number: 1 */
764	  ADC_CTL1 |= (1u << 3);                   /* reset calibration */
765	  while (ADC_CTL1 & (1u << 3));
766	  ADC_CTL1 |= (1u << 2);                   /* start calibration */
767	  while (ADC_CTL1 & (1u << 2));
768	
769	  printf("SPECTRUM: ADC0 CH18(PA4) 14bit ready\n");
770	}
771	
772	static void spectrum_init_once(void)
773	{
774	  if (!g_spec_inited)
775	    {
776	      adc0_init();
777	      g_spec_inited = 1;
778	    }
779	}
780	
781	/* Sample FFT_N points (software trigger) from external signal on PA4. */
782	static void adc_sample(void)
783	{
784	  int i;
785	
786	  RCU_APB2EN |= (1u << 8);             /* keep ADC0 clock alive (some path clears it) */
787	
788	  for (i = 0; i < FFT_N; i++)
789	    {
790	      ADC_RSQ8 = ((807u & 0x3FFu) << 5) | 0x12u;  /* re-arm rank0 = CH18 */
791	      ADC_STAT = ~(1u << 1);               /* clear EOC (stdlib adc_flag_clear) */
792	      ADC_CTL1 |= (1u << 30);              /* software start */
793	      {
794	        int spins = 0;
795	
796	        while (!(ADC_STAT & (1u << 1)))    /* wait EOC, bounded */
797	          {
798	            if (++spins > 200000)
799	              {
800	                g_adc_err++;
801	                break;
802	              }
803	          }
804	      }
805	      g_re[i] = (float)(ADC_RDATA & 0x3FFF);
806	      g_im[i] = 0.0f;
807	
808	      {
809	        int v = (int)g_re[i];
810	
811	        if (i == 0) { g_adc_min = g_adc_max = v; }
812	        if (v < g_adc_min) { g_adc_min = v; }
813	        if (v > g_adc_max) { g_adc_max = v; }
814	        g_adc_avg += v;
815	      }
816	    }
817	
818	  g_adc_avg /= FFT_N;
819	}
820	
821	/* In-place radix-2 FFT, float.  Twiddle constants are precomputed per
822	 * stage (no math.h dependency). */
823	static void fft_radix2(void)
824	{
825	  static const float tw[8][2] =
826	  {
827	    { -1.0f, 0.0f },           /* len=2   */
828	    {  0.0f, 1.0f },           /* len=4   */
829	    {  0.70710678f,  0.70710678f },
830	    {  0.92387953f,  0.38268343f },
831	    {  0.98078528f,  0.19509032f },
832	    {  0.99518473f,  0.09801714f },
833	    {  0.99879546f,  0.04906767f },
834	    {  0.99969882f,  0.02454123f },
835	  };
836	  int n = FFT_N, i, j, len, k;
837	
838	  for (i = 1, j = 0; i < n; i++)
839	    {
840	      int bit = n >> 1;
841	
842	      for (; j & bit; bit >>= 1) { j ^= bit; }
843	      j ^= bit;
844	      if (i < j)
845	        {
846	          float tr = g_re[i]; g_re[i] = g_re[j]; g_re[j] = tr;
847	          float ti = g_im[i]; g_im[i] = g_im[j]; g_im[j] = ti;
848	        }
849	    }
850	
851	  for (len = 2, k = 0; len <= n; len <<= 1, k++)
852	    {
853	      float wr = tw[k][0], wi = tw[k][1];
854	
855	      for (i = 0; i < n; i += len)
856	        {
857	          float cwr = 1.0f, cwi = 0.0f;
858	          int half = len >> 1;
859	
860	          for (j = 0; j < half; j++)
861	            {
862	              int a = i + j;
863	              int b = a + half;
864	              float tr = g_re[b] * cwr - g_im[b] * cwi;
865	              float ti = g_re[b] * cwi + g_im[b] * cwr;
866	
867	              g_re[b] = g_re[a] - tr;
868	              g_im[b] = g_im[a] - ti;
869	              g_re[a] += tr;
870	              g_im[a] += ti;
871	
872	              {
873	                float nwr = cwr * wr - cwi * wi;
874	                cwi = cwr * wi + cwi * wr;
875	                cwr = nwr;
876	              }
877	            }
878	        }
879	    }
880	}
881	
882	static void spectrum_draw(void)
883	{
884	  int i, peak = 1;
885	  float pmax = 0.0f;
886	
887	  spectrum_init_once();
888	  adc_sample();                       /* fill g_re[] with real samples */
889	
890	  /* left: time-domain waveform */
891	  fb_fill(SP_X, SP_Y, SP_W, SP_H, C_WHITE);
892	  for (i = 1; i < FFT_N; i++)
893	    {
894	      int x0 = SP_X + (i - 1) * SP_W / FFT_N;
895	      int y0 = SP_Y + (int)((16383.0f - g_re[i - 1]) * SP_H / 16384.0f);
896	      int x1 = SP_X + i * SP_W / FFT_N;
897	      int y1 = SP_Y + (int)((16383.0f - g_re[i]) * SP_H / 16384.0f);
898	
899	      draw_line(x0, y0, x1, y1, 2, C_BLACK);
900	    }
901	  draw_rect(SP_X, SP_Y, SP_W, SP_H, C_BORDER);
902	
903	  /* right: magnitude spectrum, 128 bins, fixed 14-bit full-scale */
904	  for (i = 1; i < FFT_N / 2; i++)
905	    {
906	      float mag = sqrtf(g_re[i] * g_re[i] + g_im[i] * g_im[i]);
907	
908	      if (mag > pmax) { pmax = mag; peak = i; }
909	    }
910	
911	  fb_fill(FF_X, FF_Y, FF_W, FF_H, C_WHITE);
912	  for (i = 1; i < FFT_N / 2; i++)
913	    {
914	      float mag = sqrtf(g_re[i] * g_re[i] + g_im[i] * g_im[i]);
915	      int h = (int)(mag * SP_H / 1040.0f);
916	
917	      if (h > SP_H) { h = SP_H; }
